const u = $input.first().json;
if (!Number.isSafeInteger(u.update_id) || u.update_id < 0) return [];
const m = u.message;
const allowedChats = ["0"];
if (!m || m.chat?.type !== "private" || !allowedChats.includes(String(m.chat.id)) || m.from?.is_bot !== false) return [];
return [{json:u}];

const polishTimeFormatter = new Intl.DateTimeFormat("pl-PL", {
  timeZone:"Europe/Warsaw", year:"numeric", month:"2-digit", day:"2-digit",
  hour:"2-digit", minute:"2-digit", second:"2-digit", hourCycle:"h23"
});
const formatPolishTime = value => {
  if (!value) return "not specified";
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return "invalid date";
  const p = Object.fromEntries(polishTimeFormatter.formatToParts(date).map(p=>[p.type,p.value]));
  return p.day+"."+p.month+"."+p.year+" "+p.hour+":"+p.minute+":"+p.second;
};
const u = $("Receive message").first().json;
const m = u.message;
const base = {update_id:u.update_id,chat_id:String(m?.chat?.id ?? ""),action:"reply",reply:""};
const result = value => [{json:{...base,...value}}];
if (typeof m.text !== "string") return result({reply:"Send a text command: /add, /list, /del or /status."});
const text = m.text.trim();
const match = text.match(/^\/([a-z]+)(?:@([a-z0-9_]+))?(?:\s+([\s\S]*))?$/i);
const interval = $("C Plan").first().json.interval_seconds;
const MAX_SEARCHES = 15;
const help = "Commands:\n/add Name link — add a search (no more than "+MAX_SEARCHES+")\n/list — list of searches and their IDs\n/del ID — delete a search (the ID is in /list, /status and on every card)\n/status — status of the service, searches and queue\n/perf — load and performance\n/history [N] — history for 24 h or N hours (up to 168)\n/interval N — how often to check, 10 to 360 seconds\n/on — turn on monitoring and sending; only items that appear after turning on will arrive\n/on all — switch on and send what was missed during the pause (whatever is still on the first page)\n/off — stop monitoring and sending\n\nExamples:\n/add Sneakers 44 https://www.marketplace.example/catalog?catalog[]=1231&size_ids[]=788&price_to=300\n/del tg_476200981\n\nCopy the link for /add from the browser address bar once the needed filters are set on the marketplace.\n\nHow it works:\n🔄 Every "+interval+" seconds the bot checks all searches at once. The check itself takes a few seconds, so each search is checked roughly every "+interval+" seconds. It looks at the first page of the search, where the newest items are.\n🆕 An item the bot has not yet seen in this search is sent to all members right away: photo, price and an «Open on marketplace» button.\n🤫 A newly added search first silently remembers the items already there, so only truly new ones arrive.\n⏳ If the marketplace is temporarily unavailable or rate-limits requests, the bot waits and retries. Errors are shown in /status.\n✏️ To change filters, delete the search (/del) and add it again (/add).\n📋 Number of searches cannot exceed "+MAX_SEARCHES+". To add a new one beyond the limit, first delete one you no longer need (/del).";
if (!match || match[2]) return result({reply:help});
const cmd = match[1].toLowerCase();
const args = (match[3] ?? "").trim();
const searches = $("Read searches").all().map(i => i.json).filter(s => s.search_id);
const queue = cmd === "status" || cmd === "perf" ? $("Read queue").all().map(i => i.json).filter(n => n.item_id) : [];
const workflows = new Map($input.all().map(i=>i.json).filter(w=>w.id).map(w=>[String(w.id),w]));
const producerId = "WORKFLOW_MONITOR";
const senderId = "WORKFLOW_SENDER";
const knownService = [producerId,senderId].every(id=>workflows.has(id) && typeof workflows.get(id).active === "boolean");
const serviceLine = knownService
  ? "Monitoring: " + (workflows.get(producerId).active ? "enabled" : "off") + ". Sending: " + (workflows.get(senderId).active ? "enabled" : "disabled") + "."
  : "Could not determine monitoring and sender state.";
if (cmd === "on" || cmd === "off") {
  if (args && !(cmd === "on" && args.toLowerCase() === "all")) return result({reply:cmd === "on" ? "Usage: /on or /on all" : "Usage: /off"});
  if (!knownService) return result({reply:serviceLine+" State unchanged."});
  const enabled = cmd === "on";
  const ids = enabled ? [senderId,producerId] : [producerId,senderId];
  const targets = ids.filter(id=>workflows.get(id).active !== enabled);
  if (!targets.length) return result({reply:enabled ? "Monitoring and sending are already on." : "Monitoring and sending are already off. Bot commands are available."});
  const fresh = enabled && !args && searches.length > 0;
  const reply = enabled
    ? (fresh
      ? "Monitoring and sending are on, starting fresh. The queue has been cleared; each search will first silently remember the current items, so you will only get new ones that appear after switching on. The first cycle takes up to a couple of minutes."
      : "Monitoring and sending are on. Items that appeared during the pause and are still visible on the first page of the search will arrive now; the queue is kept.")
    : "Monitoring, sending and nightly cleanup are paused. Searches, history and the queue are kept. An operation already in progress may finish. Bot commands are available.\nTurn back on:\n/on — only new items will arrive\n/on all — send what was missed during the pause (whatever is still on the first page)";
  return targets.map(id=>({json:{...base,action:cmd,fresh,target_id:id,target_version:workflows.get(id).versionId,reply},pairedItem:{item:0}}));
}
if (cmd === "interval") {
  if (!args) return result({reply:"Cycle interval: "+interval+" s. Change: /interval N, where N is from 10 to 360 seconds."});
  if (!/^\d{1,3}$/.test(args) || Number(args) < 10 || Number(args) > 360) return result({reply:"Usage: /interval N, where N is a whole number from 10 to 360 seconds. Current: "+interval+" s."});
  const seconds = Number(args);
  if (seconds === interval) return result({reply:"Cycle interval is already "+seconds+" s."});
  return result({action:"interval",interval_seconds:seconds,reply:"Cycle interval changed: "+interval+" → "+seconds+" s. Takes effect from the next cycle."});
}
if (cmd === "start" || cmd === "help") return result({reply:help});
if (cmd === "list") {
  if (args) return result({reply:"Usage: /list"});
  return result({reply:searches.length ? searches.map(s => s.search_id + " — " + s.name + " (" + (s.enabled ? "enabled" : "off") + ")").join("\n").slice(0,3500) : "No searches yet.\n"+help});
}
if (cmd === "history") {
  if (args && !/^\d{1,3}$/.test(args) || args && (Number(args) < 1 || Number(args) > 168))
    return result({reply:"Usage: /history — last 24 hours, /history N — last N hours, from 1 to 168."});
  const hours = args ? Number(args) : 24;
  const H = 3600e3, now = Date.now();
  const step = hours <= 36 ? H : hours <= 72 ? 3 * H : 6 * H;
  const end = Math.ceil(now / H) * H;
  const rows = Math.ceil(hours * H / step), start = end - rows * step;
  const samples = $("HS Measurements").all().map(i => i.json).filter(s => s.sampled_at)
    .map(s => ({ ...s, t: Date.parse(s.sampled_at) })).filter(s => s.t >= start && s.t < end).sort((a, b) => a.t - b.t);
  if (!samples.length) return result({reply:"📈 ⟦b⟧History⟦/b⟧\n\nNo measurements for this period. They are recorded every 5 minutes from the moment it is turned on."});
  const fmt = new Intl.DateTimeFormat("pl-PL", { timeZone:"Europe/Warsaw", day:"2-digit", month:"2-digit", hour:"2-digit", minute:"2-digit", hourCycle:"h23" });
  const at = t => Object.fromEntries(fmt.formatToParts(new Date(t)).map(p => [p.type, p.value]));
  const hm = t => { const p = at(t); return p.hour + ":" + p.minute; };
  const dm = t => { const p = at(t); return p.day + "." + p.month; };
  const when = t => hours > 24 ? dm(t) + " " + hm(t) : hm(t);
  const val = v => v === null || v === undefined || v === "" || !Number.isFinite(Number(v)) ? null : Number(v);
  const avg = a => { const v = a.filter(x => x !== null); return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null; };
  const sum = a => a.filter(x => x !== null).reduce((s, x) => s + x, 0);
  const fx = (v, d = 0) => v === null ? "—" : v.toFixed(d).replace(".", ",");
  const notes = s => { try { return JSON.parse(s.notes || "{}") || {}; } catch (e) { return {}; } };
  const flagged = s => val(s.errors) > 0 || (notes(s).rate || []).length > 0 || (notes(s).failed || []).length > 0 || notes(s).restart || (notes(s).alerts || []).some(a => a.startsWith("⚠"));
  const bucket = (from, size) => {
    const b = samples.filter(s => s.t >= from && s.t < from + size);
    const withCards = b.filter(s => val(s.cards) > 0 && val(s.delay_avg_s) !== null);
    return { from, has: b.length > 0, cards: b.length ? sum(b.map(s => val(s.cards))) : null,
      delay: withCards.length ? sum(withCards.map(s => s.delay_avg_s * s.cards)) / sum(withCards.map(s => val(s.cards))) : null,
      cycle: avg(b.map(s => val(s.cycle_s))), cpu: avg(b.map(s => val(s.cpu_pct))), rss: avg(b.map(s => val(s.rss_mb))), warn: b.some(flagged) };
  };
  const lp = (s, n) => (" ".repeat(n) + s).slice(-n);
  const pad = (s, n) => (s + " ".repeat(n)).slice(0, n);

  // Charts: each column is a whole clock interval (1 h for 24 h), at most 24 columns, from the first sample.
  const first = samples[0].t, last = samples[samples.length - 1].t;
  const size = [5, 10, 15, 30, 60, 120, 180, 240, 360, 480, 720].map(m => m * 60000)
    .find(s => Math.floor(last / s) - Math.floor(first / s) < 24) || 720 * 60000;
  const c0 = Math.floor(first / size) * size, W = Math.floor(last / size) - Math.floor(first / size) + 1;
  const cols = Array.from({ length: W }, (_, i) => bucket(c0 + i * size, size));
  // With few columns every column is widened so the chart stays about 24 characters wide.
  const k = Math.max(1, Math.floor(24 / W)), CW = W * k;
  const blocks = " ▁▂▃▄▅▆▇█";
  const specs = [["Cards", "cards", "", 0, true], ["Cycle", "cycle", "s", 1, true], ["CPU n8n", "cpu", "%", 0, true], ["n8n memory", "rss", "MB", 0, false]]
    .map(([title, key, unit, d, fromZero]) => {
      const v = cols.map(c => c[key]), ok = v.filter(x => x !== null);
      const hi = Math.max(...ok), lo = fromZero ? 0 : Math.min(...ok);
      // A constant series is drawn as one bottom row labelled with its value.
      return { title: title + (unit ? ", " + unit : ""), v, hi, lo, top: hi === lo ? "" : fx(hi, d), bottom: fx(lo, d) };
    });
  // One label width for all charts keeps their axes in one vertical line.
  const wy = Math.max(...specs.map(s => Math.max(s.top.length, s.bottom.length)));
  // Time ruler: start of the first column (left), start of a middle column (┬), end of the last column (right).
  const marks = [[0, c0, 0]], mid = Math.round(W / 2);
  if (mid * k - 2 >= 7 && mid * k + 3 <= CW - 6) marks.push([mid * k, c0 + mid * size, mid * k - 2]);
  marks.push([-1, c0 + W * size, CW - 5]);
  let shownDate = "";
  const tick = Array(CW).fill("─"), times = Array(CW).fill(" "), dates = Array(CW).fill(" ");
  for (const [x, t, at] of marks) {
    if (x >= 0) tick[x] = "┬";
    [...hm(t)].forEach((c, j) => times[at + j] = c);
    // The date is shown at the start and wherever it changes.
    if (dm(t) !== shownDate) [...(shownDate = dm(t))].forEach((c, j) => dates[at + j] = c);
  }
  const ruler = [" ".repeat(wy) + " └" + tick.join(""), " ".repeat(wy + 2) + times.join(""), " ".repeat(wy + 2) + dates.join("")].join("\n");
  const level = (s, x) => x === null ? -1 : s.hi === s.lo ? (s.hi > 0 ? 8 : 0) : Math.round((x - s.lo) / (s.hi - s.lo) * 24);
  // Zero shows as a thin baseline, a missing sample as "·".
  const cell = (l, r) => { if (l < 0) return r === 0 ? "·" : " "; const c = Math.max(0, Math.min(8, l - r * 8)); return c === 0 && r === 0 ? "▁" : blocks[c]; };
  const draw = s => {
    const row = r => s.v.map(x => cell(level(s, x), r).repeat(k)).join("");
    return [s.title, lp(s.top, wy) + " ┤" + row(2), " ".repeat(wy) + " │" + row(1), lp(s.bottom, wy) + " ┤" + row(0), ruler].join("\n");
  };
  const colSize = size >= 3600e3 ? size / 3600e3 + " h" : size / 60000 + " min";
  const coverage = first > start + step / 2 ? " · data from " + when(first) : "";
  const charts = specs.map(draw).join("\n\n");

  // Table: one row per step, newest first.
  const label = t => step === H ? hm(t) : dm(t) + " " + at(t).hour + "h";
  const lw = step === H ? 5 : 9;
  const tableRows = Array.from({ length: rows }, (_, i) => bucket(end - (rows - i) * step, step)).filter(b => b.has).reverse().map(b =>
    pad(label(b.from), lw) + lp(b.cards === null ? "—" : String(b.cards), 5) + lp(b.delay === null ? "—" : fx(b.delay, 1), 7)
      + lp(fx(b.cycle, 1), 6) + lp(b.cpu === null ? "—" : fx(b.cpu) + "%", 5) + lp(fx(b.rss), 6) + (b.warn ? " ⚠" : ""));
  const head = pad(step === H ? "Hour" : "Period", lw) + lp("Cards", 5) + lp("Delay", 7) + lp("Cycle", 6) + lp("CPU", 5) + lp("Mem", 6);

  // Summary.
  const peakOf = (key, d, unit) => { const s = samples.filter(x => val(x[key]) !== null); if (!s.length) return "no data";
    const top = s.reduce((a, b) => val(b[key]) > val(a[key]) ? b : a);
    return "avg " + fx(avg(s.map(x => val(x[key]))), d) + unit + " · max " + fx(val(top[key]), d) + unit + " at " + when(top.t); };
  const delayed = samples.filter(x => val(x.cards) > 0 && val(x.delay_avg_s) !== null);
  const delayTop = delayed.length ? delayed.reduce((a, b) => val(b.delay_max_s) > val(a.delay_max_s) ? b : a) : null;
  const stale = samples.filter(s => val(s.stale_s) !== null);
  const staleTop = stale.length ? stale.reduce((a, b) => val(b.stale_s) > val(a.stale_s) ? b : a) : null;
  const errorsTotal = sum(samples.map(s => val(s.errors)));
  const summary = [
    "📦 Cards: ⟦b⟧" + sum(samples.map(s => val(s.cards))) + "⟦/b⟧ · 🔁 resends: " + sum(samples.map(s => val(s.retries))) + " · " + (errorsTotal ? "❌" : "✅") + " errors: " + errorsTotal,
    "⏱ Until sending: " + (delayTop ? "avg " + fx(sum(delayed.map(x => x.delay_avg_s * x.cards)) / sum(delayed.map(x => val(x.cards))), 1) + " s · max " + fx(val(delayTop.delay_max_s), 1) + " s at " + when(delayTop.t) : "no cards"),
    "🔄 Cycle: " + peakOf("cycle_s", 1, " s"),
    "🖥 CPU n8n: " + peakOf("cpu_pct", 0, "%"),
    "⚙️ n8n executions: " + peakOf("exec_rate", 1, "/s"),
    "🕰 Stalest search: " + (staleTop ? fx(val(staleTop.stale_s)) + " s at " + when(staleTop.t) : "no data"),
  ];

  // Events with time; consecutive 429 samples are merged into one interval.
  const events = [];
  let rate = null;
  // Search IDs become tap-to-copy so the search can be removed with /del right away.
  const ids = searches.map(s => s.search_id).filter(id => /^[A-Za-z0-9_-]+$/.test(id));
  const copyIds = s => ids.length ? s.replace(new RegExp("(?<![A-Za-z0-9_-])(" + ids.join("|") + ")(?![A-Za-z0-9_-])", "g"), "⟦code⟧$1⟦/code⟧") : s;
  // Older samples store only search names for 429; the ID is looked up among current searches.
  const withId = name => { const found = searches.filter(s => s.name === name).map(s => s.search_id); return found.length ? name + " (" + found.join(", ") + ")" : name; };
  const add = (t, icon, text) => events.push({ t, text: icon + " ⟦b⟧" + text.split("\u0000")[0] + "⟦/b⟧ " + copyIds(text.split("\u0000")[1] || "") });
  const flush = () => { if (rate) add(rate.from, "🚫", (rate.to > rate.from ? when(rate.from) + "–" + hm(rate.to) : when(rate.from)) + "\u0000Marketplace 429: " + [...rate.names].map(withId).join(", ")); rate = null; };
  for (const s of samples) {
    const n = notes(s);
    if ((n.rate || []).length) { if (!rate) rate = { from: s.t, to: s.t, names: new Set() }; rate.to = s.t; n.rate.forEach(x => rate.names.add(x)); } else flush();
    if (n.restart) add(s.t, "🔄", when(s.t) + "\u0000n8n restart");
    for (const [wf, c] of Object.entries(n.errors || {})) add(s.t, "❌", when(s.t) + "\u0000run errors: " + wf + " — " + c);
    for (const f of n.failed || []) add(s.t, "📭", when(s.t) + "\u0000not delivered: " + String(f).slice(0, 60));
    for (const a of (n.alerts || []).map(String)) if (!a.includes("429"))
      a.startsWith("✅") ? add(s.t, "✅", when(s.t) + "\u0000recovered: " + a.replace(/^✅ Recovered: /, "").slice(0, 110))
        : add(s.t, "⚠️", when(s.t) + "\u0000" + a.replace(/^⚠️ /, "").slice(0, 110));
  }
  flush();
  events.sort((a, b) => b.t - a.t);

  const build = limit => {
    const shown = events.slice(0, limit), more = events.length - shown.length;
    return "📈 ⟦b⟧History for " + hours + " h⟦/b⟧\n⟦i⟧" + dm(start) + " " + hm(start) + " → " + dm(end) + " " + hm(end) + coverage + "⟦/i⟧\n\n"
      + "📊 ⟦b⟧Charts⟦/b⟧\n⟦i⟧Single bar — " + colSize + ". Below the axis — time and date: start on the left, ┬ — middle, right end.⟦/i⟧\n⟦pre⟧" + charts + "⟦/pre⟧\n"
      + "📋 ⟦b⟧" + (step === H ? "Hourly" : "By " + step / H + " h") + "⟦/b⟧ ⟦i⟧(⚠ — there were 429s, errors or failures)⟦/i⟧\n⟦pre⟧" + head + "\n" + tableRows.join("\n") + "⟦/pre⟧\n"
      + "🧾 ⟦b⟧Total⟦/b⟧\n" + summary.join("\n") + "\n⟦i⟧Measurements: " + samples.length + ", every 5 min⟦/i⟧\n\n"
      + "⚡ ⟦b⟧Events⟦/b⟧\n" + (shown.length ? shown.map(e => e.text).join("\n") + (more ? "\n⟦i⟧… plus " + more + " earlier⟦/i⟧" : "") : "No events ✅");
  };
  let limit = 30, reply = build(limit);
  while (reply.length > 3900 && limit > 0) reply = build(limit -= 5);
  return result({reply:reply.slice(0, 3900)});
}
if (cmd === "perf") {
  if (args) return result({reply:"Usage: /perf"});
  const now = Date.now();
  const sec = ms => (ms / 1000).toFixed(1).replace(".", ",") + " s";
  const metric = (text, name) => { const m = String(text || "").match(new RegExp("^" + name + "(?:\\{[^}]*\\})? (\\S+)$", "m")); return m ? Number(m[1]) : NaN; };
  const sample = node => { const j = $(node).first().json; return { text: j.data ?? j.body ?? "", at: Date.parse(j.read_at || "") }; };
  const lines = [];

  const monitor = $("PF Monitor").all().map(i => i.json).find(r => r.name === "monitor") || {};
  const cycle = Date.parse(monitor.last_completed_at) - Date.parse(monitor.last_started_at);
  lines.push(Number.isFinite(cycle) && cycle >= 0
    ? "Last cycle: " + sec(cycle) + " at interval " + interval + " s (margin " + Math.max(0, Math.round(100 - cycle / 10 / interval)) + "%)"
    : "Last cycle: no data");

  const day = queue.filter(n => n.status === "sent" && Date.parse(n.sent_at) >= now - 864e5);
  const delays = day.map(n => Date.parse(n.sent_at) - Date.parse(n.createdAt)).filter(d => Number.isFinite(d) && d >= 0);
  lines.push(delays.length
    ? "From find to sending over 24 hours: average " + sec(delays.reduce((a, b) => a + b, 0) / delays.length) + ", maximum " + sec(Math.max(...delays)) + " (" + delays.length + " cards)"
    : "From discovery to sending over 24 h: no cards");
  const pending = queue.filter(n => n.status === "pending");
  lines.push("Queue: " + pending.length + (pending.length ? ", oldest waiting " + sec(now - Math.min(...pending.map(n => Date.parse(n.createdAt)))) : ""));

  const ex = $("PF Errors").first().json;
  const errors = Array.isArray(ex.body?.data) ? ex.body.data.filter(e => Date.parse(e.startedAt) >= now - 864e5).length : null;
  lines.push("Failed executions in 24 h: " + (errors === null ? "no data" : errors >= 250 ? "250 and more" : errors));
  lines.push("Searches with errors: " + searches.filter(s => s.enabled && s.last_error).length + " of " + searches.filter(s => s.enabled).length);

  const a = sample("PF Metrics 1"), b = sample("PF Metrics 2");
  const cpu = (metric(b.text, "n8n_process_cpu_seconds_total") - metric(a.text, "n8n_process_cpu_seconds_total")) / ((b.at - a.at) / 1000);
  const rss = metric(b.text, "n8n_process_resident_memory_bytes");
  const lag = metric(b.text, "n8n_nodejs_eventloop_lag_p99_seconds");
  const started = metric(b.text, "n8n_process_start_time_seconds");
  // Split by status and mode labels; the total is the sum of all lines.
  const runs = [...String(b.text).matchAll(/^n8n_workflow_execution_duration_seconds_count(?:\{[^}]*\})? (\S+)$/gm)].reduce((s, m) => s + Number(m[1]), 0);
  if (Number.isFinite(rss)) {
    lines.push("");
    lines.push("n8n (main process):");
    if (Number.isFinite(cpu)) lines.push("CPU: " + Math.round(cpu * 100) + "% of one core (over 2 s)");
    lines.push("Memory: " + Math.round(rss / 1048576) + " MB");
    if (Number.isFinite(lag)) lines.push("Internal loop delay (p99): " + Math.round(lag * 1000) + " ms");
    if (Number.isFinite(started)) {
      const up = now / 1000 - started;
      lines.push("Running without restart: " + (up >= 86400 ? Math.floor(up / 86400) + " d " : "") + Math.floor(up % 86400 / 3600) + " h " + Math.floor(up % 3600 / 60) + " min");
      if (Number.isFinite(runs) && up > 0) lines.push("Executions since start: " + runs + " (" + (runs / up).toFixed(1).replace(".", ",") + " per second)");
    }
  } else lines.push("", "n8n metrics unavailable (requires N8N_METRICS=true).");
  return result({reply:"Performance\n" + lines.join("\n")});
}
if (cmd === "status") {
  if (args) return result({reply:"Usage: /status"});
  const pending = queue.filter(n => n.status === "pending").length;
  // "Read queue" also returns rows sent in the last 24 h; one row = one card of one search.
  const dayAgo = Date.now() - 24 * 3600 * 1000;
  const sentDay = queue.filter(n => n.status === "sent" && Date.parse(n.sent_at) >= dayAgo);
  const cards = count => { const d = count % 10, h = count % 100;
    return count + " " + (d === 1 && h !== 11 ? "card" : d >= 2 && d <= 4 && (h < 12 || h > 14) ? "cards" : "cards"); };
  const lines = searches.map(s => "ID: " + s.search_id + " — " + s.name + ": " + (s.last_error ? "error: " + String(s.last_error).slice(0,180) : s.initialized ? "checked " + formatPolishTime(s.last_success_at) : "awaiting first check") + ", in 24 hours: " + cards(sentDay.filter(n => n.search_id === s.search_id).length));
  return result({reply:(serviceLine+"\nCycle interval: "+interval+" s.\nTime: Polish (Europe/Warsaw).\nSearches: "+searches.length+" of "+MAX_SEARCHES+". Enabled: "+searches.filter(s=>s.enabled).length+"\nAwaiting sending: "+pending+"\nSent in 24 hours: "+cards(sentDay.length)+"\n"+lines.join("\n")).slice(0,3500)});
}
if (cmd === "del") {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(args)) return result({reply:"Usage: /del ID (the ID is in /list, /status and on every card)"});
  const s=searches.find(s=>s.search_id===args);
  if (!s) return result({reply:"Search "+args+" not found."});
  return result({action:"delete",search_id:s.search_id,reply:"Search deleted "+s.search_id+" — "+s.name+". History and related notifications deleted; notifications of other searches are unaffected."});
}
if (cmd === "add") {
  if (searches.length >= MAX_SEARCHES) return result({reply:"Limit reached: no more than "+MAX_SEARCHES+" searches. Search not added. To add a new one, first delete one you no longer need: /del ID (list — /list)."});
  const a=args.match(/^(.+?)\s+(https:\/\/\S+)$/i);
  if (!a) return result({reply:help});
  const name=a[1].trim(), raw=a[2];
  if (!name || name.length>120) return result({reply:"Name must be 1 to 120 characters long."});
  if (!/^https:\/\/(?:www\.)?marketplace\.example\/catalog(?:\?[^#\s]*)?(?:#[^\s]*)?$/i.test(raw)) return result({reply:"An HTTPS link to a www.marketplace.example/catalog page is required."});
  let query;
  try { query=(raw.split("#")[0].split("?")[1] || "").split("&").filter(Boolean).filter(p=>{decodeURIComponent(p);return !["page","order"].includes(decodeURIComponent(p.split("=")[0]).toLowerCase());}); }
  catch { return result({reply:"The link has invalid encoding. Send the link from the browser address bar."}); }
  const url="https://www.marketplace.example/catalog?"+[...query,"page=1","order=newest_first"].join("&");
  const id="tg_"+u.update_id;
  const existing=searches.find(s=>s.search_id===id || s.url===url);
  if(existing) return result({reply:"This search is already added: "+existing.search_id+" — "+existing.name+"."});
  return result({action:"add",search_id:id,name,url,enabled:true,initialized:false,baseline_completed_at:null,applied_url:"",next_check_at:new Date().toISOString(),last_success_at:null,last_error:"",reply:"Added "+id+" — "+name+". The shared monitoring interval is used. The first check runs without notifications."});
}
return result({reply:help});

